-- PM-1: catalogue foundation (DP-031 product master, DP-032 site listing, DP-033 categories).
--
-- Runs as dp_owner (ADR-012A). Additive only: two enums, four new tables, CHECK constraints and
-- guard triggers. No existing table, column or row is changed. Prisma's drift check sees the
-- tables and the partial unique index but not the CHECK constraints and triggers;
-- test/integration/catalog-db.int.test.ts covers each of them.
--
-- Part 1 is generated by `prisma migrate diff --from-schema <main> --to-schema schema.prisma`.
-- Part 2 adds the rules Prisma cannot model. Part 3 narrows the dp_app privileges.

-- ===========================================================================================
-- Part 0: preconditions
-- ===========================================================================================

DO $$
DECLARE
  missing text;
BEGIN
  SELECT string_agg(r, ', ')
  INTO missing
  FROM unnest(ARRAY['dp_owner', 'dp_app']) AS r
  WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'PM-1: database roles missing (%); ADR-012A must be applied first', missing;
  END IF;
END $$;

-- ===========================================================================================
-- Part 1: tables and indexes (generated)
-- ===========================================================================================
