-- ===========================================================================================
-- Part 2: rules Prisma cannot model
-- ===========================================================================================

-- Product master: formats, trimmed names, bounded text, archive state consistent with status.
ALTER TABLE "Product"
  ADD CONSTRAINT "Product_code_format" CHECK ("code" ~ '^[A-Z0-9][A-Z0-9._-]{0,63}$'),
  ADD CONSTRAINT "Product_slug_format" CHECK ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  ADD CONSTRAINT "Product_name_trimmed" CHECK ("name" = btrim("name") AND "name" <> ''),
  ADD CONSTRAINT "Product_summary_trimmed" CHECK ("summary" IS NULL OR ("summary" = btrim("summary") AND "summary" <> '')),
  ADD CONSTRAINT "Product_description_length" CHECK ("description" IS NULL OR char_length("description") BETWEEN 1 AND 8000),
  ADD CONSTRAINT "Product_version_positive" CHECK ("version" >= 1),
  ADD CONSTRAINT "Product_archived_consistent" CHECK (("status" = 'ARCHIVED') = ("archivedAt" IS NOT NULL));

ALTER TABLE "ProductCategory"
  ADD CONSTRAINT "ProductCategory_slug_format" CHECK ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  ADD CONSTRAINT "ProductCategory_name_trimmed" CHECK ("name" = btrim("name") AND "name" <> ''),
  ADD CONSTRAINT "ProductCategory_not_own_parent" CHECK ("parentId" IS NULL OR "parentId" <> "id"),
  ADD CONSTRAINT "ProductCategory_sort_order_range" CHECK ("sortOrder" BETWEEN -1000000 AND 1000000),
  ADD CONSTRAINT "ProductCategory_version_positive" CHECK ("version" >= 1);

ALTER TABLE "ProductSiteListing"
  ADD CONSTRAINT "ProductSiteListing_sort_order_range" CHECK ("sortOrder" BETWEEN -1000000 AND 1000000),
  ADD CONSTRAINT "ProductSiteListing_version_positive" CHECK ("version" >= 1);

ALTER TABLE "ProductListingText"
  ADD CONSTRAINT "ProductListingText_locale_format" CHECK ("locale" ~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$'),
  ADD CONSTRAINT "ProductListingText_title_trimmed" CHECK ("title" IS NULL OR ("title" = btrim("title") AND "title" <> '')),
  ADD CONSTRAINT "ProductListingText_summary_trimmed" CHECK ("summary" IS NULL OR ("summary" = btrim("summary") AND "summary" <> '')),
  ADD CONSTRAINT "ProductListingText_description_length" CHECK ("description" IS NULL OR char_length("description") BETWEEN 1 AND 8000);

-- Category tree: a parent is of the same site, the tree has no cycle and at most three levels.
-- Applies to the moved category's whole subtree (its deepest descendant counts).
CREATE FUNCTION catalog_category_tree_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE
  parent_site uuid;
  ancestor_depth int;
  subtree_height int;
BEGIN
  IF NEW."parentId" IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT "siteId" INTO parent_site FROM "ProductCategory" WHERE "id" = NEW."parentId";
  IF parent_site IS DISTINCT FROM NEW."siteId" THEN
    RAISE EXCEPTION 'catalog: a category parent must belong to the same site'
      USING ERRCODE = 'check_violation';
  END IF;
  -- Ancestors of the new parent (the parent itself is depth 1). Reaching NEW.id is a cycle.
  WITH RECURSIVE up("id", "parentId", depth) AS (
    SELECT c."id", c."parentId", 1 FROM "ProductCategory" c WHERE c."id" = NEW."parentId"
    UNION ALL
    SELECT c."id", c."parentId", up.depth + 1
    FROM "ProductCategory" c JOIN up ON c."id" = up."parentId"
    WHERE up.depth < 10
  )
  SELECT max(depth) INTO ancestor_depth FROM up;
  IF EXISTS (
    WITH RECURSIVE up2("id", "parentId", depth) AS (
      SELECT c."id", c."parentId", 1 FROM "ProductCategory" c WHERE c."id" = NEW."parentId"
      UNION ALL
      SELECT c."id", c."parentId", up2.depth + 1
      FROM "ProductCategory" c JOIN up2 ON c."id" = up2."parentId"
      WHERE up2.depth < 10
    )
    SELECT 1 FROM up2 WHERE up2."id" = NEW."id"
  ) THEN
    RAISE EXCEPTION 'catalog: a category cannot be moved below itself'
      USING ERRCODE = 'check_violation';
  END IF;
  -- Height of NEW's own subtree (a leaf is 1).
  WITH RECURSIVE down("id", height) AS (
    SELECT NEW."id", 1
    UNION ALL
    SELECT c."id", down.height + 1
    FROM "ProductCategory" c JOIN down ON c."parentId" = down."id"
    WHERE down.height < 10
  )
  SELECT max(height) INTO subtree_height FROM down;
  IF ancestor_depth + subtree_height > 3 THEN
    RAISE EXCEPTION 'catalog: categories have at most three levels'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;

CREATE TRIGGER "ProductCategory_tree_guard" BEFORE INSERT OR UPDATE OF "parentId", "siteId" ON "ProductCategory"
  FOR EACH ROW EXECUTE FUNCTION catalog_category_tree_guard();

-- Site and ownership columns never change: a row moves to another site or product only by being
-- created there, so the site scope of existing rows (and their audit trail) stays true. One
-- function per table: PL/pgSQL does not short-circuit AND, so a shared function could not test a
-- column that only some of the tables have.
CREATE FUNCTION catalog_category_site_immutable() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW."siteId" IS DISTINCT FROM OLD."siteId" THEN
    RAISE EXCEPTION 'catalog: ProductCategory.siteId cannot change' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;

CREATE FUNCTION catalog_listing_site_immutable() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW."siteId" IS DISTINCT FROM OLD."siteId" THEN
    RAISE EXCEPTION 'catalog: ProductSiteListing.siteId cannot change' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."productId" IS DISTINCT FROM OLD."productId" THEN
    RAISE EXCEPTION 'catalog: ProductSiteListing.productId cannot change' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;

CREATE FUNCTION catalog_listing_text_site_immutable() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW."siteId" IS DISTINCT FROM OLD."siteId" THEN
    RAISE EXCEPTION 'catalog: ProductListingText.siteId cannot change' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."listingId" IS DISTINCT FROM OLD."listingId" THEN
    RAISE EXCEPTION 'catalog: ProductListingText.listingId cannot change' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;

CREATE TRIGGER "ProductCategory_site_immutable" BEFORE UPDATE ON "ProductCategory"
  FOR EACH ROW EXECUTE FUNCTION catalog_category_site_immutable();
CREATE TRIGGER "ProductSiteListing_site_immutable" BEFORE UPDATE ON "ProductSiteListing"
  FOR EACH ROW EXECUTE FUNCTION catalog_listing_site_immutable();
CREATE TRIGGER "ProductListingText_site_immutable" BEFORE UPDATE ON "ProductListingText"
  FOR EACH ROW EXECUTE FUNCTION catalog_listing_text_site_immutable();

-- ===========================================================================================
-- Part 3: privileges (ADR-012A default privileges gave dp_app full DML on the new tables)
-- ===========================================================================================

-- Products, listings and their texts are never deleted by the API: products are archived and
-- listings hidden, so history and audit references stay valid. Empty categories may be deleted.
REVOKE DELETE ON TABLE "Product", "ProductSiteListing", "ProductListingText" FROM dp_app;
